import org.eclipse.rdf4j.sail.lmdb.LmdbOwnedCacheCodecTestSupport;
import org.junit.jupiter.api.Test;

/** A derived mask kernel must not extend an executable query's input/value lifetime. */
class PackedBindingFactsOwnershipTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final PackedStatementPatternSemanticsCodec CODEC = LmdbOwnedCacheCodecTestSupport.codec();
	private static final PackedPlanCache.Context CONTEXT = new PackedPlanCache.Context(1, 2, 3, 4, 5, 6, 7);
	private static final Set<String> MASK_CONTAINERS = Set.of(PackedMaskInterner.class.descriptorString(),
			PackedMaskLayout.class.descriptorString(), PackedMaskLayout.Kind.class.descriptorString());

	@Test
	void retainedFactsContainOnlyPrimitiveMaskState() throws Exception {
		// Parse compiled field descriptors using Java 25's standard Class-File API. No reflective object-field
		// access, GC timing, forced collection, private-state writes or caller callbacks are involved.
		for (Class<?> type : List.of(PackedBindingFacts.class, PackedMaskInterner.class, PackedMaskLayout.class)) {
			try (InputStream bytes = type.getResourceAsStream(type.getSimpleName() + ".class")) {
				assertNotNull(bytes, "the actual compiled mask class must be available");
				for (FieldModel field : ClassFile.of().parse(bytes.readAllBytes()).fields()) {
					ClassDesc descriptor = field.fieldTypeSymbol();
					assertTrue(primitiveStorage(descriptor) || MASK_CONTAINERS.contains(descriptor.descriptorString()),
							() -> type.getSimpleName() + "." + field.fieldName().stringValue() + " -> "
									+ descriptor.descriptorString()
									+ ": derived masks must not retain queries, input rows, values or callbacks");
				}
			}
		}
	}

	@Test
	void ordinaryOwnedValuesKeepARealWarmHitAndIsolatedEmissions() {
		BindingSetAssignment source = assignment();
		BindingSet originalRow = source.getBindingSets().iterator().next();
		Value originalValue = originalRow.getValue("value");
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		PackedPlanningResult cold = plan(cache, source);
		PackedPlanningResult hot = plan(cache, source);
		PackedPlanningResult repeated = plan(cache, source);
		assertFalse(cold.metrics().planCacheHit());
		assertTrue(hot.metrics().planCacheHit(), "the production owned codec must retain an ordinary VALUES query");
		assertTrue(repeated.metrics().planCacheHit());
		List<BindingSet> expected = rows(source);
		List<BindingSet> first = rows((BindingSetAssignment) hot.selectedPlan());
		List<BindingSet> second = rows((BindingSetAssignment) repeated.selectedPlan());
		assertEquals(expected, first, "duplicates and the nullable declared column must survive");
		assertEquals(expected, second);
		assertEquals(3, first.size());
		assertNotSame(originalRow, first.get(0));
		assertNotSame(first.get(0), second.get(0));
		assertNotSame(originalValue, first.get(0).getValue("value"));
		assertNotSame(first.get(0).getValue("value"), second.get(0).getValue("value"));
		assertSame(originalRow, source.getBindingSets().iterator().next());
		assertSame(originalValue, originalRow.getValue("value"));
	}

	@Test
	void detachedAndReboundQueriesKeepTheirDerivedMaskAndNullableSchemaSemantics() {
		BindingSetAssignment source = assignment();
		PackedQuery original = PackedQueryCodec.encodeForPlanning(source, null, CODEC);
		PackedQuery detached = original.withoutOriginalBindingSets();
		PackedQuery rebound = PackedQueryCodec.rebindOriginalBindingSets(detached, assignment());
		assertFalse(detached.originalBindingSetsAttached());
		assertThrows(IllegalStateException.class, () -> detached.originalBindingSets(detached.rootRelId()));
		sameMasks(original, detached);
		sameMasks(original, rebound);
		PackedQuery parameterized = PackedQueryCodec.encodeForParameterizedPlanning(source, null, CODEC);
		PackedQuery template = parameterized.withoutOriginalBindingSets().withoutInvocationParameters();
		assertFalse(template.originalBindingSetsAttached());
		assertEquals(0, template.parameterVector().size());
		sameMasks(parameterized, template);
		BindingSetAssignment output = (BindingSetAssignment) PackedPlanMaterializer.materialize(rebound,
				rebound.rootRelId());
		assertEquals(Set.of("value", "nullable"), output.getDeclaredBindingNames());
		assertEquals(Set.of("value"), output.getAssuredBindingNames());
		assertEquals(rows(source), rows(output));
	}

	@Test
	void defaultCodecStillRebindsTheCurrentCallersActualRows() {
		BindingSetAssignment cold = assignment();
		BindingSetAssignment current = assignment();
		BindingSet currentRow = current.getBindingSets().iterator().next();
		PackedQuery original = PackedQueryCodec.encode(cold);
		assertSame(cold.getBindingSets(), original.originalBindingSets(original.rootRelId()));
		PackedQuery detached = original.withoutOriginalBindingSets();
		PackedQuery rebound = PackedQueryCodec.rebindOriginalBindingSets(detached, current);
		BindingSetAssignment output = (BindingSetAssignment) PackedPlanMaterializer.materialize(rebound,
				rebound.rootRelId());
		assertSame(current.getBindingSets(), output.getBindingSets());
		assertSame(currentRow, output.getBindingSets().iterator().next());
		assertNotSame(cold.getBindingSets().iterator().next(), currentRow);
		sameMasks(original, detached);
		sameMasks(original, rebound);
	}

	private static boolean primitiveStorage(ClassDesc type) {
		while (type.isArray()) {
			type = type.componentType();
		}
		return type.isPrimitive();
	}

	private static void sameMasks(PackedQuery expected, PackedQuery actual) {
		assertEquals(expected.relationCount(), actual.relationCount());
		assertEquals(expected.scalarCount(), actual.scalarCount());
		for (int relation = 1; relation <= expected.relationCount(); relation++) {
			assertEquals(expected.relOutputMaskId(relation), actual.relOutputMaskId(relation));
			assertEquals(expected.relAssuredMaskId(relation), actual.relAssuredMaskId(relation));
			assertEquals(expected.relRequiredInputMaskId(relation), actual.relRequiredInputMaskId(relation));
			assertEquals(expected.relProtectedInputMaskId(relation), actual.relProtectedInputMaskId(relation));
			assertEquals(expected.relIndependentOutputMaskId(relation), actual.relIndependentOutputMaskId(relation));
			assertEquals(expected.relNullableInputMaskId(relation), actual.relNullableInputMaskId(relation));
			assertEquals(expected.relOrdinaryWriteMaskId(relation), actual.relOrdinaryWriteMaskId(relation));
			int output = actual.relOutputMaskId(relation);
			int assured = actual.relAssuredMaskId(relation);
			assertEquals(expected.maskCardinality(expected.relOutputMaskId(relation)), actual.maskCardinality(output));
			assertTrue(actual.maskContainsAll(output, assured));
			assertEquals(assured, actual.intersectMasks(output, assured));
			assertEquals(output, actual.unionMasks(output, assured));
		}
		for (int scalar = 1; scalar <= expected.scalarCount(); scalar++) {
			assertEquals(expected.scalarDependencyMaskId(scalar), actual.scalarDependencyMaskId(scalar));
			assertEquals(expected.scalarEmbeddedReferenceMaskId(scalar), actual.scalarEmbeddedReferenceMaskId(scalar));
			assertEquals(expected.scalarSafeToRelocate(scalar), actual.scalarSafeToRelocate(scalar));
			assertEquals(expected.scalarSafeWhenAssured(scalar), actual.scalarSafeWhenAssured(scalar));
		}
	}

	private static PackedPlanningResult plan(PackedPlanCache cache, BindingSetAssignment source) {
		return PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), cache, CONTEXT,
				(query, relation) -> 3.0d, null, CODEC);
	}

	private static BindingSetAssignment assignment() {
		List<String> names = List.of("value", "nullable");
		List<BindingSet> rows = List.of(new ListBindingSet(names, VF.createLiteral("same"), null),
				new ListBindingSet(names, VF.createLiteral("same"), null),
				new ListBindingSet(names, VF.createLiteral("other"), VF.createIRI("urn:optional")));
		BindingSetAssignment result = new BindingSetAssignment();
		result.setBindingNames(Set.copyOf(names));
		result.setBindingSets(rows);
		return result;
	}

	private static List<BindingSet> rows(BindingSetAssignment assignment) {
		List<BindingSet> result = new ArrayList<>();
		assignment.getBindingSets().forEach(result::add);
		return result;
	}
}
